 Check(!StagePolicy.LoopbackGateway("ws://remote.example:18789")&&!StagePolicy.LoopbackGateway("ws://127.0.0.1:18789/?token=x")&&StagePolicy.LoopbackGateway("ws://127.0.0.1:18789"),"gateway accepts only plain loopback endpoint");Check(!StagePolicy.LocalPath(@"\\server\data",true,"Ubuntu")&&StagePolicy.LocalPath(@"\\wsl.localhost\Ubuntu\home\fixture",true,"Ubuntu"),"only correlated local WSL share accepted");Check(StagePolicy.SafeLink("codex://threads/"+uuid,"codex")!=null&&StagePolicy.SafeLink("https://example.com","codex")==null,"deep-link whitelist");Check(!StagePolicy.MutationAuthorized(true,null,true,"id","codex","Title","C:\\Fixture",null,null,1),"native mutation requires verified supervisor");Check(StagePolicy.ValidateSendText(new string('中',2001))=="text_invalid"&&StagePolicy.ValidateSendText("ok\0")=="text_invalid","invalid prompts rejected");var clean=BridgeRequestGuard.Sanitize(new Dictionary<string,object?>{{"command","malicious"},{"text","hello"},{"environment","x"}});Check(clean.Count==1&&clean.ContainsKey("text"),"request cannot choose executable or environment");
 var multilingual=new Dictionary<string,object?>{{"id","fixture"},{"text",string.Concat(Enumerable.Repeat("😀",2000))}};var encoded=BridgeRequestGuard.Encode(multilingual,out var encodeError);
 Check(encoded!=null&&encodeError==null&&encoded.Length<=32768,"full 2000-scalar Unicode prompt fits bounded UTF-8 protocol");
