 Check(!StagePolicy.MetadataCarriesThread("draft "+uuid,"composer","",new[]{uuid},false),"draft text UUID cannot prove current thread");
 Check(StagePolicy.MetadataCarriesThread("","thread-"+uuid,"",new[]{uuid},false),"non-content current metadata can identify thread");
 Check(!StagePolicy.MetadataCarriesThread("","composer","quoted "+uuid,new[]{uuid},false),"arbitrary help text is not navigation identity");
 var rage=new RadarSettings{Mode="rage"};Check(ContinuationPolicy.Resume("grok",rage)==ContinuationPolicy.GrokResumeText,"Grok recovery default in rage mode");rage.ResumeText="common resume";Check(ContinuationPolicy.Resume("codex",rage)=="common resume","generic recovery used in rage mode");
 Console.WriteLine(JsonSerializer.Serialize(new{all_passed=true,checks=count,external_sends=0}));
}finally{Directory.Delete(root,true);}
static SessionRecord Row(int n,double now,string status)=>new(){Id="codex:"+n.ToString("x8")+"-1111-4111-8111-111111111111",AppId="codex",AppName="Codex",Title="Fixture "+n,Project=@"C:\Fixture",Status=status,Source="local-session",StartedAt=now-50,UpdatedAt=now,TimingBasis="turn",Target="codex://threads/"+n.ToString("x8")+"-1111-4111-8111-111111111111"};
sealed class Clock{public DateTimeOffset Value=DateTimeOffset.FromUnixTimeSeconds(1791809000);public double Now=>Value.ToUnixTimeMilliseconds()/1000d;public void Advance(double s)=>Value=Value.AddSeconds(s);}
sealed class Worker(Clock clock):IWorkerClient{public event Action<CollectorSnapshot>? Snapshot;public event Action<string>? Fault{add{}remove{}}public List<Dictionary<string,object?>> Requests=[];public Task StartAsync(CancellationToken t=default)=>Task.CompletedTask;public void Stop(){}public void Dispose(){}public void Publish(params SessionRecord[] rows)=>Snapshot?.Invoke(new(){Sessions=rows.Select(SessionFacts.Clone).ToList(),CollectedAt=clock.Now});public Task<BridgeResult> RunBridgeAsync(Dictionary<string,object?> q,CancellationToken t=default){Requests.Add(q);return Task.FromResult(new BridgeResult{Code="sent_pending_confirmation",Attempted=true,SentAt=clock.Now,RunId="fixture-new-run"});}}
sealed class Platform:IPlatformServices{public int Navigations;public double IdleSeconds{get;set;}=100;public bool DesktopUsable{get;set;}=true;public Task<NavigationResult> OpenAsync(SessionRecord s,CancellationToken t=default){Navigations++;return Task.FromResult(new NavigationResult(false,"fixture"));}public Task<string> CheckAccessibilityAsync(CancellationToken t=default)=>Task.FromResult("fixture");public void SetKeepAwake(bool e){}public void SetStartup(bool e){}}
